import '@xterm/xterm/css/xterm.css'

import {Link} from '@primer/react'
import {useCallback, useEffect, useRef, useState} from 'react'
import type {ReactNode} from 'react'

import {isFeatureEnabled} from '@github-ui/feature-flags'
import {useDevTunnelsPortStream} from '../hooks/use-connector-stream'
import {useTerminalStream} from '../hooks/use-terminal-stream'
import {useXtermPortTerminal} from '../hooks/use-xterm-terminal'
import {useCodespace} from '../hooks/use-codespace'
import type {WebCopilotCliProps} from '../types'
import {CliBanner} from './CliBanner'

const URL_REGEX = /https?:\/\/[^\s]+/g

function linkifyText(text: string): ReactNode {
  const parts: ReactNode[] = []
  let lastIndex = 0
  for (const match of text.matchAll(URL_REGEX)) {
    const url = match[0]
    if (match.index == null) continue
    const start = match.index
    if (start > lastIndex) parts.push(text.slice(lastIndex, start))
    parts.push(
      <Link key={start} href={url} target="_blank" rel="noopener noreferrer">
        {url}
      </Link>,
    )
    lastIndex = start + url.length
  }
  if (lastIndex < text.length) parts.push(text.slice(lastIndex))
  return parts
}

export function WebCopilotCli({
  repository,
  sessionId,
  codespaceId,
  onConnected,
  onError,
  onCodespaceConnected,
}: WebCopilotCliProps) {
  const {codespaceState, creationErrorMessage, codespaceInfo, remoteProvider, reconnectCodespace} = useCodespace({
    repository,
    codespaceId,
  })

  const [connected, setConnected] = useState(false)
  const [connectionError, setConnectionError] = useState<string | null>(null)
  const wasConnectedRef = useRef(false)
  const onConnectedRef = useRef(onConnected)
  const onErrorRef = useRef(onError)
  const onCodespaceConnectedRef = useRef(onCodespaceConnected)
  const writeToTerminalRef = useRef<(data: unknown) => void>(() => {})
  const sendInputRef = useRef<(data: string) => void>(() => {})
  const sendResizeRef = useRef<(cols: number, rows: number) => void>(() => {})

  useEffect(() => {
    onConnectedRef.current = onConnected
    onErrorRef.current = onError
    onCodespaceConnectedRef.current = onCodespaceConnected
  }, [onConnected, onError, onCodespaceConnected])

  useEffect(() => {
    // eslint-disable-next-line no-console
    console.log('[WebCopilotCli] codespaceState:', codespaceState, 'hasProvider:', !!remoteProvider)
  }, [codespaceState, remoteProvider])

  const handleTerminalInput = useCallback((data: string) => {
    sendInputRef.current(data)
  }, [])

  const handleTerminalResize = useCallback((cols: number, rows: number) => {
    sendResizeRef.current(cols, rows)
  }, [])

  const {
    terminalBackground,
    terminalForeground,
    terminalContainerRef,
    writeToTerminal,
    flushTerminalDecoder,
    getTerminalSize,
  } = useXtermPortTerminal({
    active: codespaceState === 'ready',
    onInput: handleTerminalInput,
    onResize: handleTerminalResize,
  })

  useEffect(() => {
    writeToTerminalRef.current = writeToTerminal
  }, [writeToTerminal])

  const handleStreamData = useCallback((data: unknown) => {
    writeToTerminalRef.current(data)
  }, [])

  const triggerReconnect = useCallback(() => {
    if (!wasConnectedRef.current) return false
    wasConnectedRef.current = false
    setConnectionError(null)
    setConnected(false)
    void reconnectCodespace()
    return true
  }, [reconnectCodespace])

  const handleStreamClose = useCallback(() => {
    flushTerminalDecoder()
    setConnected(false)
    triggerReconnect()
  }, [flushTerminalDecoder, triggerReconnect])

  const useTmux = isFeatureEnabled('copilot_cli_in_web_poc_tmux')

  const handleStreamError = useCallback(
    (message: string) => {
      if (!triggerReconnect()) {
        setConnectionError(message)
      }
    },
    [triggerReconnect],
  )

  // Both hooks must be called unconditionally (rules of hooks).
  // Only one is activated via the `active` flag.
  const portStream = useDevTunnelsPortStream({
    active: codespaceState === 'ready' && !useTmux,
    tunnelProperties: codespaceInfo?.environment_data.connection.tunnelProperties,
    remoteProvider,
    tuiSessionId: sessionId,
    onData: handleStreamData,
    onClose: handleStreamClose,
    onError: handleStreamError,
  })
  const tmuxStream = useTerminalStream({
    active: codespaceState === 'ready' && useTmux,
    tunnelProperties: codespaceInfo?.environment_data.connection.tunnelProperties,
    remoteProvider,
    tuiSessionId: sessionId,
    onData: handleStreamData,
    onClose: handleStreamClose,
    onError: handleStreamError,
  })

  const {transportReady, sendInput, sendResize} = useTmux ? tmuxStream : portStream

  useEffect(() => {
    sendInputRef.current = sendInput
    sendResizeRef.current = sendResize
  }, [sendInput, sendResize])

  useEffect(() => {
    if (!transportReady || !codespaceInfo) {
      return
    }

    // Wait for a measurable terminal viewport before sending the first resize.
    // Sending 0x0 can leave the remote TUI non-rendering until a manual resize.
    let cancelled = false
    let frameId: number | undefined
    const trySendInitialResize = (attempt = 0) => {
      if (cancelled) return

      const {cols, rows} = getTerminalSize()
      if (cols > 0 && rows > 0) {
        sendResize(cols, rows)
        return
      }

      if (attempt < 30) {
        frameId = requestAnimationFrame(() => {
          trySendInitialResize(attempt + 1)
        })
      }
    }

    trySendInitialResize()

    const t = setTimeout(() => {
      setConnectionError(null)
      setConnected(true)
      wasConnectedRef.current = true
      onConnectedRef.current?.()
      onCodespaceConnectedRef.current?.(codespaceInfo.cloud_environment.guid)
    }, 1)

    return () => {
      cancelled = true
      if (frameId !== undefined) cancelAnimationFrame(frameId)
      clearTimeout(t)
    }
  }, [codespaceInfo, getTerminalSize, sendResize, transportReady])

  useEffect(() => {
    if (codespaceState !== 'failed' || !creationErrorMessage) {
      return
    }
    onErrorRef.current?.(creationErrorMessage)
  }, [codespaceState, creationErrorMessage])

  useEffect(
    () => () => {
      flushTerminalDecoder()
    },
    [flushTerminalDecoder],
  )

  if (codespaceState === 'failed') {
    return (
      <div style={{height: '100%'}}>
        <div role="alert" style={{padding: 'var(--base-size-8)', color: 'var(--fgColor-danger)'}}>
          <span>{`Failed to start codespace: ${creationErrorMessage ?? 'Unknown error'}`}</span>
        </div>
      </div>
    )
  }

  return (
    <div
      style={{
        backgroundColor: terminalBackground,
        color: terminalForeground,
        height: '100%',
        display: 'flex',
        flexDirection: 'column',
      }}
    >
      {!connected && !connectionError && <CliBanner />}
      {connectionError && (
        <div
          role="alert"
          style={{padding: 'var(--base-size-8)', color: 'var(--fgColor-danger)', whiteSpace: 'pre-wrap'}}
        >
          {linkifyText(connectionError)}
        </div>
      )}
      <div ref={terminalContainerRef} className="height-full overflow-hidden" style={{flex: 1}} />
    </div>
  )
}
