import {TerminalIcon} from '@primer/octicons-react'
import {IconButton} from '@primer/react'
import {useState} from 'react'

import type {WebTerminalRepository} from '../types'
import {WebTerminalPanel} from './WebTerminalPanel'

export interface CopilotWebCliLauncherProps {
  repository: WebTerminalRepository
  currentUserId?: number
}

/**
 * Drop-in component that renders an IconButton to launch the Copilot CLI
 * terminal overlay panel. Import this into any page to get the button and
 * panel together; the component manages its own open/close state.
 */
export function CopilotWebCliLauncher({repository, currentUserId}: CopilotWebCliLauncherProps) {
  const [isOpen, setIsOpen] = useState(false)
  const [hasBeenOpened, setHasBeenOpened] = useState(false)

  const handleToggle = () => {
    setIsOpen(prev => !prev)
    setHasBeenOpened(true)
  }

  return (
    <>
      <IconButton
        icon={TerminalIcon}
        aria-label="Launch Copilot CLI terminal"
        aria-expanded={isOpen}
        onClick={handleToggle}
        data-testid="repo-cli-button"
      />
      {hasBeenOpened && (
        <WebTerminalPanel
          isOpen={isOpen}
          onClose={() => setIsOpen(false)}
          repository={repository}
          currentUserId={currentUserId}
        />
      )}
    </>
  )
}
