import {CopilotIcon, ListUnorderedIcon, PlusIcon, ScreenFullIcon, ScreenNormalIcon, XIcon} from '@primer/octicons-react'
import {IconButton, Spinner} from '@primer/react'
import {useCallback, useEffect, useMemo, useReducer, useRef, useState} from 'react'

import type {ApiTaskWithCompute} from '../hooks/use-cli-tasks'
import {useCliTasks, getAgentTaskId} from '../hooks/use-cli-tasks'
import {createCodespace, cloudEnvironmentUrl} from '../utils/codespace-lifecycle'
import type {WebTerminalRepository} from '../types'
import {CliBanner} from './CliBanner'
import {CliTaskList} from './CliTaskList'
import {panelReducer, initialPanelState, isCreating, resolveSelectedTask} from '../utils/panel-reducer'
import styles from './WebTerminalPanel.module.css'
import {WebCopilotCli} from './WebCopilotCli'

const MIN_PANEL_HEIGHT = 300
const DEFAULT_PANEL_HEIGHT = 600
const MAX_PANEL_HEIGHT_RATIO = 0.8
const MAX_CONCURRENT_SESSIONS = 3

const terminalContainerStyle: React.CSSProperties = {
  backgroundColor: '#0c0c0c',
  color: '#cccccc',
  height: '100%',
  display: 'flex',
  flexDirection: 'column',
}

export interface WebTerminalPanelProps {
  isOpen: boolean
  onClose: () => void
  repository: WebTerminalRepository
  currentUserId?: number
}

export function WebTerminalPanel({isOpen, onClose, repository, currentUserId}: WebTerminalPanelProps) {
  const [panelHeight, setPanelHeight] = useState(DEFAULT_PANEL_HEIGHT)
  const [isMaximized, setIsMaximized] = useState(false)
  const isDraggingRef = useRef(false)
  const startYRef = useRef(0)
  const startHeightRef = useRef(0)
  const creatingInFlightRef = useRef(false)

  const [state, dispatch] = useReducer(panelReducer, initialPanelState)

  const {tasks, isLoading, error, refetch, refetchUntilCodespace, archiveTask} = useCliTasks({
    owner: repository.ownerLogin,
    repo: repository.name,
    currentUserId,
  })

  // Refresh the task list each time the panel is re-opened so we don't
  // operate on a stale list.
  const prevIsOpenRef = useRef(isOpen)
  useEffect(() => {
    if (isOpen && !prevIsOpenRef.current) {
      refetch()
    }
    prevIsOpenRef.current = isOpen
  }, [isOpen, refetch])

  const creating = isCreating(state)

  const selectedTask = useMemo(() => resolveSelectedTask(state, tasks, isLoading), [state, tasks, isLoading])
  const sessionId = selectedTask ? getAgentTaskId(selectedTask) : undefined
  const codespaceId = selectedTask?.compute?.resource_id
  const isActive = selectedTask !== undefined

  // During provisioning we have a codespace but no task yet. Render the
  // terminal so it can send the handshake that creates the task record.
  const provisioningCodespaceId =
    !isActive && state.creation.phase === 'provisioning' ? state.creation.codespaceId : undefined
  const showTerminal = isActive || provisioningCodespaceId !== undefined
  const effectiveCodespaceId = codespaceId ?? provisioningCodespaceId

  // When a provisioning task appears in the task list, auto-select and complete creation
  useEffect(() => {
    if (state.creation.phase !== 'provisioning') return
    const csId = state.creation.codespaceId
    const task = tasks.find(t => t.compute?.resource_id === csId)
    if (task) {
      dispatch({type: 'SELECT_TASK', taskId: task.id})
    }
  }, [state.creation, tasks])

  const startNewSession = useCallback(async () => {
    if (creatingInFlightRef.current) return
    creatingInFlightRef.current = true
    dispatch({type: 'START_CREATION'})

    try {
      const baseUrl = cloudEnvironmentUrl(repository.ownerLogin, repository.name)
      const data = await createCodespace(baseUrl, repository.branchName)
      const guid = data.cloud_environment.guid
      dispatch({type: 'CREATION_PROVISIONING', codespaceId: guid})
      // useCodespace inside WebCopilotCli handles waiting for the codespace
      // to become available before connecting the tunnel.
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err)
      dispatch({type: 'CREATION_FAILED', message: msg})
    } finally {
      creatingInFlightRef.current = false
    }
  }, [repository.ownerLogin, repository.name, repository.branchName])

  // Auto-create on first load when no tasks exist (only once)
  const startNewSessionRef = useRef(startNewSession)
  useEffect(() => {
    startNewSessionRef.current = startNewSession
  }, [startNewSession])

  useEffect(() => {
    if (!isLoading && tasks.length === 0 && !state.hasAutoCreated && !creatingInFlightRef.current) {
      dispatch({type: 'SET_AUTO_CREATED'})
      void startNewSessionRef.current()
    }
  }, [isLoading, tasks.length, state.hasAutoCreated])

  const handleTaskClick = useCallback((task: ApiTaskWithCompute) => {
    dispatch({type: 'SELECT_TASK', taskId: task.id})
  }, [])

  const handleNewSession = useCallback(() => {
    const effectiveCount = tasks.length + (creating ? 1 : 0)
    if (effectiveCount >= MAX_CONCURRENT_SESSIONS) {
      dispatch({
        type: 'CREATION_FAILED',
        message: `Maximum ${MAX_CONCURRENT_SESSIONS} concurrent sessions reached. Archive a session before creating a new one.`,
      })
      return
    }
    dispatch({type: 'HIDE_SESSION_LIST'})
    void startNewSession()
  }, [tasks.length, creating, startNewSession])

  const handleArchive = useCallback(
    async (task: ApiTaskWithCompute) => {
      await archiveTask(task.id)
      if (selectedTask?.id === task.id) {
        dispatch({type: 'CLEAR_SELECTION'})
      }
    },
    [archiveTask, selectedTask?.id],
  )

  const handleCodespaceConnected = useCallback(
    (csId: string) => {
      refetchUntilCodespace(csId)
    },
    [refetchUntilCodespace],
  )

  // When the codespace for the selected task is gone (404), refetch the
  // task list — filterStaleTasks will archive it and remove it from the list.
  const handleCodespaceError = useCallback(
    (_message: string) => {
      refetch()
      dispatch({type: 'CLEAR_SELECTION'})
    },
    [refetch],
  )

  const sessionListRef = useRef<HTMLDivElement>(null)

  // Close the session list when clicking outside of it
  useEffect(() => {
    if (!state.showSessionList) return

    const handleClickOutside = (e: MouseEvent) => {
      if (sessionListRef.current && !sessionListRef.current.contains(e.target as Node)) {
        dispatch({type: 'HIDE_SESSION_LIST'})
      }
    }

    document.addEventListener('mousedown', handleClickOutside)
    return () => document.removeEventListener('mousedown', handleClickOutside)
  }, [state.showSessionList])

  // Arrow keys for resize control — not a keyboard shortcut
  const onKeyDown = useCallback((e: React.KeyboardEvent) => {
    const RESIZE_STEP = 40
    // eslint-disable-next-line @github-ui/ui-commands/no-manual-shortcut-logic
    const direction = e.key === 'ArrowUp' ? 1 : e.key === 'ArrowDown' ? -1 : 0
    if (direction === 0) return
    e.preventDefault()
    const maxHeight = window.innerHeight * MAX_PANEL_HEIGHT_RATIO
    setPanelHeight(h => Math.min(maxHeight, Math.max(MIN_PANEL_HEIGHT, h + direction * RESIZE_STEP)))
  }, [])

  const onMouseDown = useCallback(
    (e: React.MouseEvent) => {
      isDraggingRef.current = true
      startYRef.current = e.clientY
      startHeightRef.current = panelHeight
      e.preventDefault()
    },
    [panelHeight],
  )

  useEffect(() => {
    const onMouseMove = (e: MouseEvent) => {
      if (!isDraggingRef.current) return
      const delta = startYRef.current - e.clientY
      const maxHeight = window.innerHeight * MAX_PANEL_HEIGHT_RATIO
      const newHeight = Math.min(maxHeight, Math.max(MIN_PANEL_HEIGHT, startHeightRef.current + delta))
      setPanelHeight(newHeight)
    }

    const onMouseUp = () => {
      isDraggingRef.current = false
    }

    document.addEventListener('mousemove', onMouseMove)
    document.addEventListener('mouseup', onMouseUp)
    return () => {
      document.removeEventListener('mousemove', onMouseMove)
      document.removeEventListener('mouseup', onMouseUp)
    }
  }, [])

  const handleToggleMaximize = useCallback(() => {
    setIsMaximized(prev => !prev)
  }, [])

  if (!isOpen) return null

  const creationError = state.creation.phase === 'error' ? state.creation.message : null

  return (
    <div
      className={styles.Panel}
      role="region"
      aria-label="Copilot CLI terminal"
      style={{height: isMaximized ? `${MAX_PANEL_HEIGHT_RATIO * 100}vh` : panelHeight}}
    >
      <button
        className={styles.ResizeHandle}
        aria-label="Resize terminal panel"
        onMouseDown={onMouseDown}
        onKeyDown={onKeyDown}
        type="button"
      />
      <div className={styles.Header}>
        <span className={styles.HeaderTitle}>
          <CopilotIcon size={16} />
          <span>Copilot CLI</span>
        </span>
        <span className={styles.HeaderActions}>
          {tasks.length > 0 && (
            <IconButton
              icon={ListUnorderedIcon}
              aria-label={state.showSessionList ? 'Hide sessions' : 'Show sessions'}
              aria-expanded={state.showSessionList}
              variant="invisible"
              size="small"
              onClick={() => dispatch({type: 'TOGGLE_SESSION_LIST'})}
              onMouseDown={e => e.stopPropagation()}
            />
          )}
          {creating ? (
            <Spinner size="small" />
          ) : (
            <IconButton
              icon={PlusIcon}
              aria-label="New session"
              variant="invisible"
              size="small"
              onClick={handleNewSession}
              onMouseDown={e => e.stopPropagation()}
            />
          )}
          <IconButton
            icon={isMaximized ? ScreenNormalIcon : ScreenFullIcon}
            aria-label={isMaximized ? 'Restore panel size' : 'Maximize panel'}
            variant="invisible"
            size="small"
            onClick={handleToggleMaximize}
            onMouseDown={e => e.stopPropagation()}
          />
          <IconButton
            icon={XIcon}
            aria-label="Close terminal"
            variant="invisible"
            size="small"
            onClick={onClose}
            onMouseDown={e => e.stopPropagation()}
          />
        </span>
      </div>
      <div className={styles.TerminalContainer}>
        {state.showSessionList && (
          <div ref={sessionListRef} className={styles.SessionListDropdown}>
            <CliTaskList
              tasks={tasks}
              isLoading={isLoading}
              error={error}
              activeTaskId={selectedTask?.id}
              isCreating={creating}
              onTaskClick={handleTaskClick}
              onArchive={handleArchive}
            />
          </div>
        )}
        {isLoading && !isActive && !creating && (
          <div style={terminalContainerStyle}>
            <CliBanner showSpinner={false} statusText="" />
          </div>
        )}
        {creationError && !isActive && (
          <div style={terminalContainerStyle}>
            <CliBanner showSpinner={false} />
            <div role="alert" className="p-2 color-fg-danger">
              {creationError}
            </div>
          </div>
        )}
        {creating && !showTerminal && !creationError && (
          <div style={terminalContainerStyle}>
            <CliBanner />
          </div>
        )}
        {showTerminal && (
          <WebCopilotCli
            key={effectiveCodespaceId}
            repository={repository}
            sessionId={sessionId}
            codespaceId={effectiveCodespaceId}
            onCodespaceConnected={handleCodespaceConnected}
            onError={handleCodespaceError}
          />
        )}
      </div>
    </div>
  )
}
