import {useCallback, useEffect, useMemo, useRef, useState} from 'react'
import {useIdleTimer} from 'react-idle-timer'

import {type CodespaceInfoBase, CodespaceStateInfo} from '@github-ui/workspace-editor/utilities/workspace-editor-types'

import type {UseCodespaceOptions} from '../types'
import {
  cloudEnvironmentUrl,
  createCodespace,
  getCodespaceInfo,
  startCodespace as startExistingCodespace,
  waitForCodespaceAvailable,
} from '../utils/codespace-lifecycle'
import {RemoteProvider} from '@github/codespaces-ssh-tunneling'

type CodespaceState = 'none' | 'creating' | 'starting' | 'ready' | 'failed'

interface CodespaceSession {
  codespaceState: CodespaceState
  codespaceInfo: CodespaceInfoBase | null
  remoteProvider: RemoteProvider | undefined
  creationErrorMessage: string | undefined
  reconnectCodespace: () => Promise<void>
}

export function useCodespace({
  repository,
  codespaceId,
  activityNamespace = 'copilot-cli-web',
}: UseCodespaceOptions): CodespaceSession {
  const [codespaceInfo, setCodespaceInfo] = useState<CodespaceInfoBase | null>(null)
  const [codespaceState, setCodespaceState] = useState<CodespaceState>('none')
  const [creationErrorMessage, setCreationErrorMessage] = useState<string | undefined>(undefined)
  const [remoteProvider, setRemoteProvider] = useState<RemoteProvider | undefined>(undefined)
  const bootstrapInFlightRef = useRef(false)

  const baseUrl = useMemo(
    () => cloudEnvironmentUrl(repository.ownerLogin, repository.name),
    [repository.ownerLogin, repository.name],
  )

  const activeGuidRef = useRef<string | undefined>(codespaceId)

  const applyReadyInfo = useCallback((info: CodespaceInfoBase) => {
    setCodespaceState('ready')
    setCodespaceInfo(info)
    activeGuidRef.current = info.cloud_environment.guid

    const {tunnelProperties} = info.environment_data.connection
    if (tunnelProperties) {
      setRemoteProvider(new RemoteProvider(tunnelProperties, 3))
    }
  }, [])

  const startCodespace = useCallback(async () => {
    try {
      setCodespaceState('creating')
      setCreationErrorMessage(undefined)

      const data = await createCodespace(baseUrl, repository.branchName)
      const guid = data.cloud_environment.guid

      setCodespaceState('starting')

      const readyInfo = await waitForCodespaceAvailable(baseUrl, guid)
      applyReadyInfo(readyInfo)
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : `Unknown error: ${error}`
      setCreationErrorMessage(errorMessage)
      setCodespaceState('failed')
    }
  }, [baseUrl, repository.branchName, applyReadyInfo])

  const connectToCodespace = useCallback(
    async (guid: string) => {
      try {
        setCodespaceState('starting')
        setCreationErrorMessage(undefined)

        const info = await getCodespaceInfo(baseUrl, guid)
        const {state} = info.environment_data

        let readyInfo: CodespaceInfoBase
        if (state === CodespaceStateInfo.Available) {
          readyInfo = info
        } else if (state === CodespaceStateInfo.Shutdown) {
          await startExistingCodespace(baseUrl, guid)
          readyInfo = await waitForCodespaceAvailable(baseUrl, guid)
        } else {
          // Non-terminal transitional state — poll until Available.
          // If it passes through Shutdown, waitForCodespaceAvailable restarts it automatically.
          readyInfo = await waitForCodespaceAvailable(baseUrl, guid)
        }

        applyReadyInfo(readyInfo)
      } catch (err) {
        const message = err instanceof Error ? err.message : String(err)
        if (message.includes('404')) {
          setCreationErrorMessage(
            'This is an archived session. Choose a different session or create a new session to use the CLI.',
          )
        } else {
          setCreationErrorMessage(message)
        }
        setCodespaceState('failed')
      }
    },
    [baseUrl, applyReadyInfo],
  )

  const reconnectInFlightRef = useRef(false)

  const reconnectCodespace = useCallback(async () => {
    if (reconnectInFlightRef.current) return
    const guid = activeGuidRef.current
    if (!guid) return
    reconnectInFlightRef.current = true
    try {
      setRemoteProvider(undefined)
      setCodespaceInfo(null)
      setCreationErrorMessage(undefined)
      await connectToCodespace(guid)
    } finally {
      reconnectInFlightRef.current = false
    }
  }, [connectToCodespace])

  useIdleTimer({
    onAction: async e => {
      if (!remoteProvider) return
      try {
        const activity = e?.type.replace(' ', '') || 'unknown'
        await remoteProvider.notifyClientActivity([activityNamespace, [activity]])
      } catch (error) {
        if (error instanceof Error && error.message.includes('No stream available')) {
          await reconnectCodespace()
        }
      }
    },
    throttle: 5000,
  })

  useEffect(() => {
    if (codespaceState !== 'none') return

    if (bootstrapInFlightRef.current) return
    bootstrapInFlightRef.current = true

    const bootstrap = async () => {
      try {
        if (codespaceId) {
          await connectToCodespace(codespaceId)
        } else {
          await startCodespace()
        }
      } finally {
        bootstrapInFlightRef.current = false
      }
    }

    void bootstrap()
  }, [codespaceState, codespaceId, connectToCodespace, startCodespace])

  return {
    codespaceState,
    codespaceInfo,
    remoteProvider,
    creationErrorMessage,
    reconnectCodespace,
  }
}
