import {RemoteProvider, WindowChangeRequestMessage} from '@github/codespaces-ssh-tunneling'
import {useCallback, useEffect, useRef, useState} from 'react'

type TunnelProperties = ConstructorParameters<typeof RemoteProvider>[0]
type TerminalChannel = Awaited<ReturnType<RemoteProvider['getTerminalChannel']>>

const MAX_CHANNEL_RETRIES = 10
const CHANNEL_RETRY_DELAY_MS = 3000
const STARTUP_TIMEOUT_MS = 30_000

// eslint-disable-next-line no-console
const log = (...args: unknown[]) => console.log('[tmux-stream]', ...args)

interface UseTerminalStreamArgs {
  active: boolean
  tunnelProperties?: TunnelProperties
  remoteProvider?: RemoteProvider
  tuiSessionId?: string
  onData: (data: unknown) => void
  onClose: () => void
  onError: (message: string) => void
}

// UUID pattern: only hex digits and hyphens — safe for shell interpolation.
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i

function buildTmuxCommand(sessionId: string): string {
  if (!UUID_RE.test(sessionId)) {
    throw new Error(`Invalid session ID format: ${sessionId}`)
  }
  return [
    `tmux new-session -d -A -s ${sessionId} "COPILOT_ASSOCIATE_COMPUTE=true WEB_CLI_MODE=true copilot --resume=${sessionId} --remote"`,
    `tmux set-option -t ${sessionId} status off`,
    `exec tmux attach -t ${sessionId}`,
  ].join('; ')
}

/**
 * Run a command via getCommandChannel and return its exit code.
 * Resolves with the numeric exit code, or -1 if the channel fails.
 */
async function runPreflightCheck(
  provider: RemoteProvider,
  command: string,
): Promise<{exitCode: number; stderr: string}> {
  const cmdChannel = await provider.getCommandChannel()
  let stderr = ''

  return new Promise(resolve => {
    cmdChannel.onErrorOutput(data => {
      stderr += data
    })
    cmdChannel.onExitCode(({status}) => {
      void cmdChannel.close()
      resolve({exitCode: status ?? -1, stderr})
    })
    void cmdChannel.executeCommand(command)
  })
}

const encoder = new TextEncoder()
const decoder = new TextDecoder()

export function useTerminalStream({
  active,
  tunnelProperties,
  remoteProvider: externalProvider,
  tuiSessionId,
  onData,
  onClose,
  onError,
}: UseTerminalStreamArgs) {
  const [transportReady, setTransportReady] = useState(false)
  const channelRef = useRef<TerminalChannel | null>(null)
  const onDataRef = useRef(onData)
  const onCloseRef = useRef(onClose)
  const onErrorRef = useRef(onError)
  const stableSessionNameRef = useRef<string | null>(null)

  useEffect(() => {
    onDataRef.current = onData
    onCloseRef.current = onClose
    onErrorRef.current = onError
  }, [onData, onClose, onError])

  const sendInput = useCallback((value: string) => {
    const channel = channelRef.current
    if (!channel || channel.isClosed) return
    try {
      channel.send(encoder.encode(value) as Buffer)
    } catch {
      // Channel may have been disposed between the check and send.
    }
  }, [])

  const sendResize = useCallback((cols: number, rows: number) => {
    const channel = channelRef.current
    if (!channel || channel.isClosed) return
    try {
      const msg = new WindowChangeRequestMessage(cols, rows, 0, 0)
      channel.request(msg)
    } catch {
      // Ignore resize errors on disposed/closed channels.
    }
  }, [])

  useEffect(() => {
    if (!active) {
      log('effect skipped — not active')
      return
    }

    log('effect fired — active, hasProvider:', !!externalProvider, 'hasTunnel:', !!tunnelProperties)

    if (!externalProvider && !tunnelProperties) {
      onErrorRef.current('Failed opening terminal stream – tunnel properties not available')
      return
    }

    let cancelled = false
    let startupTimer: ReturnType<typeof setTimeout> | undefined
    let retryTimer: ReturnType<typeof setTimeout> | undefined
    if (!stableSessionNameRef.current) {
      stableSessionNameRef.current = tuiSessionId ?? crypto.randomUUID()
    }
    const sessionId = stableSessionNameRef.current

    const connect = async () => {
      const t0 = performance.now()
      log('connect started')

      const provider = externalProvider ?? new RemoteProvider(tunnelProperties as TunnelProperties, 3)
      if (cancelled) return

      // Run preflight checks and warm up the terminal channel in parallel.
      // The terminal channel open is often the slowest step (SSH handshake),
      // so starting it alongside preflight saves significant time.
      log('starting preflight + terminal channel in parallel')
      const preflightPromise = (async () => {
        try {
          log('preflight: checking tmux...')
          const {exitCode: tmuxCheck} = await runPreflightCheck(provider, 'command -v tmux')
          log(`preflight: tmux check done, exit=${tmuxCheck}, +${Math.round(performance.now() - t0)}ms`)
          if (tmuxCheck !== 0) return 'tmux' as const

          log('preflight: checking copilot...')
          const {exitCode: copilotCheck} = await runPreflightCheck(provider, 'command -v copilot')
          log(`preflight: copilot check done, exit=${copilotCheck}, +${Math.round(performance.now() - t0)}ms`)
          if (copilotCheck !== 0) return 'copilot' as const

          return 'ok' as const
        } catch (err) {
          log(`preflight: failed (transient), skipping, +${Math.round(performance.now() - t0)}ms`, err)
          return 'ok' as const
        }
      })()

      const channelPromise = (async () => {
        log(`warming up terminal channel, +${Math.round(performance.now() - t0)}ms`)
        const channel = await provider.getTerminalChannel({
          term: 'xterm-256color',
          keepAliveOnData: true,
        })
        log(`terminal channel opened, +${Math.round(performance.now() - t0)}ms`)
        return channel
      })()

      // Wait for both. If channel fails, we'll catch it below.
      let preflightResult: 'ok' | 'tmux' | 'copilot'
      let warmChannel: TerminalChannel | null = null
      try {
        ;[preflightResult, warmChannel] = await Promise.all([preflightPromise, channelPromise])
      } catch (err) {
        // Channel warmup failed — preflight may have succeeded or not.
        // Fall through to retry loop without a warm channel.
        log(`parallel warmup failed, +${Math.round(performance.now() - t0)}ms`, err)
        preflightResult = await preflightPromise
        if (cancelled) return
      }

      if (cancelled) {
        warmChannel?.dispose()
        return
      }

      log(
        `parallel phase done, preflight=${preflightResult}, hasWarmChannel=${!!warmChannel}, +${Math.round(performance.now() - t0)}ms`,
      )

      const requiredFeatures: string[] = [
        '"ghcr.io/devcontainers/features/copilot-cli:1": {}',
        '"ghcr.io/devcontainers/features/sshd:1": {}',
        '"ghcr.io/devcontainers-extra/features/tmux-apt-get:1": {}',
      ]

      if (preflightResult === 'tmux') {
        warmChannel?.dispose()
        onErrorRef.current(
          `Required tools are missing. Please add the following features to the repo devcontainer.json:\n - ${requiredFeatures.join('\n - ')}`,
        )
        return
      }
      if (preflightResult === 'copilot') {
        warmChannel?.dispose()
        onErrorRef.current(
          `Copilot CLI is not installed in this codespace. Please add the following features to the repo devcontainer.json:\n - ${requiredFeatures.join('\n - ')}`,
        )
        return
      }

      for (let attempt = 1; attempt <= MAX_CHANNEL_RETRIES; attempt++) {
        if (cancelled) return

        try {
          // Use the pre-warmed channel on the first attempt.
          let channel: TerminalChannel
          if (attempt === 1 && warmChannel) {
            channel = warmChannel
            log(`attempt 1/${MAX_CHANNEL_RETRIES}: using pre-warmed channel, +${Math.round(performance.now() - t0)}ms`)
          } else {
            const retryProvider = externalProvider ?? new RemoteProvider(tunnelProperties as TunnelProperties, 3)
            log(
              `attempt ${attempt}/${MAX_CHANNEL_RETRIES}: opening terminal channel, +${Math.round(performance.now() - t0)}ms`,
            )
            channel = await retryProvider.getTerminalChannel({
              term: 'xterm-256color',
              keepAliveOnData: true,
            })
            log(`attempt ${attempt}: channel opened, +${Math.round(performance.now() - t0)}ms`)
          }

          if (cancelled) {
            channel.dispose()
            return
          }

          let startupConfirmed = false

          channel.onDataReceived((data: Buffer) => {
            if (cancelled) return
            const text = typeof data === 'string' ? data : decoder.decode(data)

            if (!startupConfirmed) {
              startupConfirmed = true
              log(`first output received, +${Math.round(performance.now() - t0)}ms`)
              setTransportReady(true)
            }

            onDataRef.current(text)
          })

          channel.onClosed(() => {
            if (startupTimer) {
              clearTimeout(startupTimer)
              startupTimer = undefined
            }
            if (!cancelled) {
              setTransportReady(false)
              onCloseRef.current()
            }
          })

          channelRef.current = channel

          const cmd = buildTmuxCommand(sessionId)
          log(`attempt ${attempt}: sending tmux command, +${Math.round(performance.now() - t0)}ms`)
          channel.send(encoder.encode(`${cmd}\n`) as Buffer)

          startupTimer = setTimeout(() => {
            if (!startupConfirmed && !cancelled) {
              log(`startup timeout after ${STARTUP_TIMEOUT_MS}ms`)
              onErrorRef.current(
                'Copilot CLI did not start within the expected time. ' +
                  'Please make sure tmux and copilot are installed in this codespace.',
              )
              channel.dispose()
            }
          }, STARTUP_TIMEOUT_MS)

          return
        } catch (err) {
          log(`attempt ${attempt}: failed, +${Math.round(performance.now() - t0)}ms`, err)
          if (cancelled) return
          if (attempt < MAX_CHANNEL_RETRIES) {
            log(`attempt ${attempt}: retrying in ${CHANNEL_RETRY_DELAY_MS}ms`)
            await new Promise<void>(resolve => {
              retryTimer = setTimeout(resolve, CHANNEL_RETRY_DELAY_MS)
            })
          }
        }
      }

      if (!cancelled) {
        onErrorRef.current('Failed to open terminal channel after multiple attempts')
      }
    }

    void connect()

    return () => {
      cancelled = true
      if (startupTimer) clearTimeout(startupTimer)
      if (retryTimer) clearTimeout(retryTimer)
      setTransportReady(false)
      channelRef.current?.dispose()
      channelRef.current = null
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [active, tunnelProperties, externalProvider])

  return {
    transportReady,
    sendInput,
    sendResize,
  }
}
