import {reactFetchJSON} from '@github-ui/verified-fetch'
import {assertValidCodespaceInfo} from '@github-ui/workspace-editor/utilities/asserts'
import {
  type CodespaceErrorResponse,
  type CodespaceInfoBase,
  CodespaceStateInfo,
} from '@github-ui/workspace-editor/utilities/workspace-editor-types'
import {withRetries} from '@github-ui/workspace-editor/utilities/with-retries'

const TERMINAL_CODESPACE_STATES = new Set<CodespaceStateInfo>([
  CodespaceStateInfo.Deleted,
  CodespaceStateInfo.Failed,
  CodespaceStateInfo.Unavailable,
])

export function cloudEnvironmentUrl(ownerLogin: string, repoName: string): string {
  return `/${ownerLogin}/${repoName}/copilot/compute/codespace`
}

export async function createCodespace(baseUrl: string, branch?: string): Promise<CodespaceInfoBase> {
  const response = await reactFetchJSON(baseUrl, {
    body: {branch},
    method: 'POST',
  })

  if (!response.ok) {
    const errorData: CodespaceErrorResponse = await response.json()
    throw new Error(errorData.error ?? `${response.status} - ${response.statusText}`)
  }

  const data: CodespaceInfoBase | object = await response.json()
  assertValidCodespaceInfo(data, 'Failed to create codespace')

  return data
}

export async function startCodespace(baseUrl: string, guid: string): Promise<CodespaceInfoBase> {
  const response = await reactFetchJSON(`${baseUrl}/${guid}/start`, {
    method: 'POST',
  })

  if (!response.ok) {
    const errorData: CodespaceErrorResponse = await response.json()
    throw new Error(errorData.error ?? `${response.status} - ${response.statusText}`)
  }

  const data: CodespaceInfoBase | object = await response.json()
  assertValidCodespaceInfo(data, 'Failed to start codespace')

  return data
}

export async function getCodespaceInfo(baseUrl: string, guid: string): Promise<CodespaceInfoBase> {
  const response = await reactFetchJSON(`${baseUrl}/${guid}`, {})
  if (!response.ok) {
    throw new Error(`Failed to fetch codespace: ${response.status}`)
  }

  const info: CodespaceInfoBase | object = await response.json()
  assertValidCodespaceInfo(info, 'Failed to validate codespace info')
  return info
}

/**
 * Polls until the codespace reaches the Available state.
 * If the codespace reaches Shutdown (e.g. after ShuttingDown), it is
 * automatically started and polling continues until Available.
 * Throws if it enters a terminal state (Failed, Deleted, etc.),
 * the caller aborts, or the default timeout (10 minutes) is exceeded.
 */
export async function waitForCodespaceAvailable(
  baseUrl: string,
  guid: string,
  signal?: AbortSignal,
): Promise<CodespaceInfoBase> {
  const DEFAULT_TIMEOUT_MS = 10 * 60 * 1000

  return await withRetries(
    async () => {
      signal?.throwIfAborted()

      const response = await reactFetchJSON(`${baseUrl}/${guid}`, {})
      if (!response.ok) {
        throw new Error('Failed to check codespace status')
      }

      const info: CodespaceInfoBase | object = await response.json()
      assertValidCodespaceInfo(info, 'Failed to refresh codespace info')

      const currentState = info.environment_data.state

      if (TERMINAL_CODESPACE_STATES.has(currentState)) {
        throw new TerminalCodespaceStateError(currentState)
      }

      if (currentState === CodespaceStateInfo.Shutdown) {
        await startCodespace(baseUrl, guid)
      }

      if (currentState !== CodespaceStateInfo.Available) {
        throw new Error('Codespace not yet available')
      }

      return info
    },
    {
      retries: Infinity,
      retryDelayMs: 1000,
      exponentialBackoffFactor: 1.02,
      timeoutMs: Date.now() + DEFAULT_TIMEOUT_MS,
      shouldStopRetries: error =>
        error instanceof TerminalCodespaceStateError || (error instanceof DOMException && error.name === 'AbortError'),
    },
  )
}

class TerminalCodespaceStateError extends Error {
  readonly codespaceState: CodespaceStateInfo

  constructor(codespaceState: CodespaceStateInfo) {
    super(`Codespace entered terminal state: ${codespaceState}`)
    this.name = 'TerminalCodespaceStateError'
    this.codespaceState = codespaceState
  }
}
