import useColorModes from '@github-ui/react-core/use-color-modes'
import {FitAddon} from '@xterm/addon-fit'
import type {ITheme} from '@xterm/xterm'
import {Terminal as XTerm} from '@xterm/xterm'
import {useCallback, useEffect, useRef} from 'react'

interface UseXtermPortTerminalArgs {
  active: boolean
  onInput: (data: string) => void
  onResize: (cols: number, rows: number) => void
}

function decodeTerminalData(data: unknown, decoder: TextDecoder): string {
  if (typeof data === 'string') {
    return data
  }

  if (data instanceof Uint8Array) {
    return decoder.decode(data, {stream: true})
  }

  if (data instanceof ArrayBuffer) {
    return decoder.decode(new Uint8Array(data), {stream: true})
  }

  if (typeof Buffer !== 'undefined' && Buffer.isBuffer(data)) {
    return data.toString('utf-8')
  }

  return String(data ?? '')
}

export function useXtermPortTerminal({active, onInput, onResize}: UseXtermPortTerminalArgs) {
  const {colorMode} = useColorModes()
  const terminalContainerRef = useRef<HTMLDivElement>(null)
  const xtermRef = useRef<XTerm | null>(null)
  const fitAddonRef = useRef<FitAddon | null>(null)
  const textDecoderRef = useRef(new TextDecoder())
  const pendingOutputRef = useRef<string[]>([])
  const onInputRef = useRef(onInput)
  const onResizeRef = useRef(onResize)

  useEffect(() => {
    onInputRef.current = onInput
    onResizeRef.current = onResize
  }, [onInput, onResize])

  useEffect(() => {
    return () => {
      pendingOutputRef.current = []
    }
  }, [])

  const terminalBackground = '#0c0c0c'
  const terminalForeground = '#cccccc'

  useEffect(() => {
    if (!active) {
      return
    }

    const xtermTheme: ITheme = {
      foreground: terminalForeground,
      background: terminalBackground,
      cursor: 'var(--fgColor-accent)',
      cursorAccent: 'var(--fgColor-accent)',
      selectionBackground: 'var(--codeMirror-selection-bgColor)',
      selectionInactiveBackground: 'var(--codeMirror-selection-bgColor)',
      black: 'var(--color-ansi-black)',
      brightBlack: 'var(--color-ansi-black-bright)',
      white: 'var(--color-ansi-white)',
      brightWhite: 'var(--color-ansi-white-bright)',
      red: 'var(--color-ansi-red)',
      brightRed: 'var(--color-ansi-red-bright)',
      green: 'var(--color-ansi-green)',
      brightGreen: 'var(--color-ansi-green-bright)',
      yellow: 'var(--color-ansi-yellow)',
      brightYellow: 'var(--color-ansi-yellow-bright)',
      blue: 'var(--color-ansi-blue)',
      brightBlue: 'var(--color-ansi-blue-bright)',
      magenta: 'var(--color-ansi-magenta)',
      brightMagenta: 'var(--color-ansi-magenta-bright)',
      cyan: 'var(--color-ansi-cyan)',
      brightCyan: 'var(--color-ansi-cyan-bright)',
    }

    const terminal = new XTerm({theme: xtermTheme})
    const fitAddon = new FitAddon()
    xtermRef.current = terminal
    fitAddonRef.current = fitAddon
    terminal.loadAddon(fitAddon)

    const resizeTerminal = () => {
      try {
        fitAddonRef.current?.fit()
        onResizeRef.current(terminal.cols, terminal.rows)
      } catch {
        // Ignore resize errors.
      }
    }

    const dataSubscription = terminal.onData(data => {
      onInputRef.current(data)
    })

    let container: HTMLDivElement | null = null
    let resizeObserver: ResizeObserver | undefined
    if (terminalContainerRef.current) {
      container = terminalContainerRef.current
      terminal.open(container)

      if (typeof ResizeObserver !== 'undefined') {
        resizeObserver = new ResizeObserver(resizeTerminal)
        resizeObserver.observe(container)
      }
    }

    if (pendingOutputRef.current.length > 0) {
      terminal.write(pendingOutputRef.current.join(''))
      pendingOutputRef.current = []
    }

    resizeTerminal()

    return () => {
      resizeObserver?.disconnect()
      dataSubscription.dispose()
      // Remove from DOM before disposing to force xterm to detach
      // document-level mouse listeners synchronously
      if (container && terminal.element) {
        container.removeChild(terminal.element)
      }
      fitAddonRef.current = null
      xtermRef.current = null
      // Defer disposal to the next frame so any pending xterm Viewport
      // requestAnimationFrame refreshes complete before the render service
      // is torn down (reduces "Cannot read properties of undefined
      // (reading 'dimensions')" errors from @xterm/xterm@6.0.0; fixed
      // upstream by xtermjs/xterm.js#5827 in 7.0).
      requestAnimationFrame(() => {
        fitAddon.dispose()
        terminal.dispose()
      })
    }
  }, [active, colorMode])

  const writeToTerminal = useCallback((data: unknown) => {
    const text = decodeTerminalData(data, textDecoderRef.current)
    if (xtermRef.current) {
      xtermRef.current.write(text)
      return
    }

    pendingOutputRef.current.push(text)
  }, [])

  const flushTerminalDecoder = useCallback(() => {
    const trailingText = textDecoderRef.current.decode()
    if (trailingText) {
      xtermRef.current?.write(trailingText)
    }
  }, [])

  const getTerminalSize = useCallback(() => {
    return {
      cols: xtermRef.current?.cols ?? 0,
      rows: xtermRef.current?.rows ?? 0,
    }
  }, [])

  return {
    terminalBackground,
    terminalForeground,
    terminalContainerRef,
    writeToTerminal,
    flushTerminalDecoder,
    getTerminalSize,
  }
}
