import {RemoteProvider} from '@github/codespaces-ssh-tunneling'
import {useCallback, useEffect, useRef, useState} from 'react'

type TunnelProperties = ConstructorParameters<typeof RemoteProvider>[0]

type PortStream = {
  write(chunk: string, cb?: (error: Error | null | undefined) => void): boolean
  on(event: string | symbol, listener: (...args: unknown[]) => void): PortStream
  destroy(error?: Error): PortStream
  writable: boolean
  destroyed: boolean
  closed: boolean
}

type TunnelProtocolArg = Exclude<Parameters<RemoteProvider['getStreamFromPort']>[1], undefined>

const HTTP_TUNNEL_PROTOCOL: TunnelProtocolArg = 'http' as TunnelProtocolArg
const RESIZE_CONTROL_PREFIX = '\x1b]RESIZE:'
const RESIZE_CONTROL_SUFFIX = '\x07'
const CONNECTOR_PORT = 3100
const MAX_RETRIES = 60
const HANDSHAKE_TIMEOUT_MS = 5000
const MIN_ATTEMPT_MS = HANDSHAKE_TIMEOUT_MS
const CONNECTOR_NOT_FOUND_MESSAGE =
  'Please make sure the copilot-connector feature and prebuild are configured for this repository by following the instructions at https://gh.io/copilot-cli-connector-install'

interface UseCodespacePortStreamArgs {
  active: boolean
  tunnelProperties?: TunnelProperties
  remoteProvider?: RemoteProvider
  tuiSessionId?: string
  onData: (data: unknown) => void
  onClose: () => void
  onError: (message: string) => void
}

/**
 * Single-attempt handshake: writes the handshake message and waits up to
 * HANDSHAKE_TIMEOUT_MS for any data to arrive (confirming the remote
 * processed it). Listeners are registered before writing to avoid missing
 * a fast response.
 */
async function waitForHandshakeAck(
  stream: PortStream,
  handshake: string,
  isCancelled: () => boolean,
  setCleanup: (cleanup: (() => void) | undefined) => void,
): Promise<boolean> {
  if (stream.destroyed || stream.closed) return false

  return new Promise<boolean>(resolve => {
    if (isCancelled()) {
      resolve(false)
      return
    }

    let settled = false
    const timer = setTimeout(() => settle(false), HANDSHAKE_TIMEOUT_MS)

    function settle(result: boolean) {
      if (settled) return
      settled = true
      clearTimeout(timer)
      resolve(result)
    }

    stream.on('data', () => settle(true))
    stream.on('close', () => settle(false))
    stream.on('error', () => settle(false))

    setCleanup(() => settle(false))

    try {
      stream.write(handshake)
    } catch {
      settle(false)
    }
  })
}

interface ConnectOptions {
  getStream: () => Promise<PortStream>
  handshake: string
  onData: (data: unknown) => void
  onClose: () => void
  onError: (message: string) => void
  isCancelled: () => boolean
  setCleanup: (cleanup: (() => void) | undefined) => void
}

/**
 * Combined port-connection + handshake retry loop. Each attempt opens a fresh
 * port stream, wires the xterm data listener, then sends the handshake and
 * waits for an ACK. If either the port or handshake fails, the stream is
 * destroyed and the whole sequence retries.
 *
 * Close/error listeners are wired immediately but only forwarded to the
 * caller after a successful handshake, so retry-phase destroys stay internal.
 *
 * Returns the connected & handshake-acked stream, or null after exhausting
 * all retries.
 */
async function connectWithHandshake({
  getStream,
  handshake,
  onData,
  onClose,
  onError,
  isCancelled,
  setCleanup,
}: ConnectOptions): Promise<PortStream | null> {
  for (let attempt = 1; attempt <= MAX_RETRIES; attempt++) {
    if (isCancelled()) return null

    const attemptStart = Date.now()
    let stream: PortStream | null = null
    try {
      stream = await getStream()

      // Gate caller-facing close/error until handshake succeeds so
      // retry-phase stream destroys don't surface to the UI.
      // Also suppress during intentional teardown (isCancelled) to
      // prevent effect cleanup from triggering a spurious reconnect.
      let handshakeComplete = false

      stream.on('data', data => onData(data))
      stream.on('close', () => {
        if (handshakeComplete && !isCancelled()) onClose()
      })
      stream.on('error', error => {
        if (handshakeComplete && !isCancelled()) {
          const message = error instanceof Error ? error.message : String(error)
          onError(message)
        }
      })

      const acked = await waitForHandshakeAck(stream, handshake, isCancelled, setCleanup)
      setCleanup(undefined)

      if (acked) {
        handshakeComplete = true
        return stream
      }

      stream.destroy?.()
    } catch {
      stream?.destroy?.()
    }

    // Ensure each attempt takes at least MIN_ATTEMPT_MS to avoid
    // rapid-fire API calls when getStream() fails fast.
    const elapsed = Date.now() - attemptStart
    if (elapsed < MIN_ATTEMPT_MS) {
      await new Promise(r => setTimeout(r, MIN_ATTEMPT_MS - elapsed))
    }
  }
  return null
}

export function useDevTunnelsPortStream({
  active,
  tunnelProperties,
  remoteProvider: externalProvider,
  tuiSessionId,
  onData,
  onClose,
  onError,
}: UseCodespacePortStreamArgs) {
  const [transportReady, setTransportReady] = useState(false)
  const streamRef = useRef<PortStream | null>(null)
  const tuiSessionIdRef = useRef(tuiSessionId)
  const onDataRef = useRef(onData)
  const onCloseRef = useRef(onClose)
  const onErrorRef = useRef(onError)

  useEffect(() => {
    tuiSessionIdRef.current = tuiSessionId
  }, [tuiSessionId])

  useEffect(() => {
    onDataRef.current = onData
    onCloseRef.current = onClose
    onErrorRef.current = onError
  }, [onData, onClose, onError])

  const writeToStream = useCallback((value: string) => {
    const stream = streamRef.current
    if (!stream || !stream.writable || stream.destroyed || stream.closed) {
      return
    }

    stream.write(value)
  }, [])

  const sendResize = useCallback(
    (cols: number, rows: number) => {
      writeToStream(`${RESIZE_CONTROL_PREFIX}${cols}:${rows}${RESIZE_CONTROL_SUFFIX}`)
    },
    [writeToStream],
  )

  useEffect(() => {
    if (!active) {
      return
    }

    if (!externalProvider && !tunnelProperties) {
      onErrorRef.current('Failed opening TUI stream - tunnel properties not available')
      return
    }

    let cancelled = false
    let cleanupTimer: (() => void) | undefined

    const connect = async () => {
      try {
        const handshake = tuiSessionIdRef.current ? `RESUME_SESSION:${tuiSessionIdRef.current}\n` : 'CREATE_SESSION\n'

        const stream = await connectWithHandshake({
          getStream: async () => {
            const provider = externalProvider ?? new RemoteProvider(tunnelProperties as TunnelProperties, 3)
            return await provider.getStreamFromPort(CONNECTOR_PORT, HTTP_TUNNEL_PROTOCOL)
          },
          handshake,
          onData: data => onDataRef.current(data),
          onClose: () => {
            setTransportReady(false)
            onCloseRef.current()
          },
          onError: message => onErrorRef.current(message),
          isCancelled: () => cancelled,
          setCleanup: cb => {
            cleanupTimer = cb
          },
        })

        if (cancelled) {
          stream?.destroy?.()
          return
        }

        if (!stream) {
          onErrorRef.current(CONNECTOR_NOT_FOUND_MESSAGE)
          return
        }

        streamRef.current = stream
        setTransportReady(true)
      } catch (err) {
        const message = err instanceof Error ? err.message : String(err)
        onErrorRef.current(message)
      }
    }

    void connect()

    return () => {
      cancelled = true
      cleanupTimer?.()
      setTransportReady(false)
      streamRef.current?.destroy?.()
      streamRef.current = null
    }
  }, [active, tunnelProperties, externalProvider, writeToStream])

  return {
    transportReady,
    sendInput: writeToStream,
    sendResize,
  }
}
