import {useState, useEffect, useCallback, useRef} from 'react'
import type {APITask} from '@github-ui/agent-sessions/types/api-task'
import {fetchCAPI} from '@github-ui/agent-sessions/utils/fetch-capi'
import {parseLinkHeader} from '@github-ui/agent-sessions/utils/pagination-helpers'
import {reactFetchJSON} from '@github-ui/verified-fetch'
import {cloudEnvironmentUrl} from '../utils/codespace-lifecycle'

interface TaskCompute {
  resource_id: string
  provider: 'codespaces' | 'sandbox'
}

export interface ApiTaskWithCompute extends APITask {
  compute: TaskCompute
}

interface TasksApiResponse {
  tasks: Array<APITask & {compute?: TaskCompute}>
}

interface UseCliTasksOptions {
  owner: string
  repo: string
  currentUserId?: number
}

interface UseCliTasksResult {
  tasks: ApiTaskWithCompute[]
  isLoading: boolean
  error: string | null
  refetch: () => void
  refetchUntilCodespace: (codespaceId: string) => void
  archiveTask: (taskId: string) => Promise<void>
}

const CLI_AGENT_SLUG = 'copilot-developer-cli'
const PAGE_SIZE = 10
const MAX_PAGES = 10
const CODESPACE_POLL_INTERVAL_MS = 3000
const CODESPACE_POLL_MAX_ATTEMPTS = 30

export function getAgentTaskId(task: APITask): string | undefined {
  return task.agent_collaborators?.find(c => c.slug === CLI_AGENT_SLUG)?.agent_task_id
}

async function fetchAllCliTasks(owner: string, repo: string, currentUserId?: number): Promise<ApiTaskWithCompute[]> {
  const allTasks: ApiTaskWithCompute[] = []

  for (let page = 1; page <= MAX_PAGES; page++) {
    const params = new URLSearchParams({
      archived: 'false',
      per_page: String(PAGE_SIZE),
      page: String(page),
    })
    if (currentUserId) {
      params.set('creator_id', String(currentUserId))
    }

    const response = await fetchCAPI({path: `/agents/repos/${owner}/${repo}/tasks?${params}`})
    if (!response.ok) {
      throw new Error(`Failed to fetch tasks: ${response.status}`)
    }

    const data: TasksApiResponse = await response.json()
    const cliTasks: ApiTaskWithCompute[] = []
    for (const task of data.tasks ?? []) {
      if (getAgentTaskId(task) !== undefined && task.compute !== undefined) {
        cliTasks.push({...task, compute: task.compute})
      }
    }
    allTasks.push(...cliTasks)

    const hasNextPage = parseLinkHeader(response.headers?.get('Link'))
    if (!hasNextPage) break
  }

  return allTasks
}

/**
 * Checks each task's codespace. Returns the subset of tasks whose codespace
 * is still reachable (non-404). Tasks whose codespace returns 404 are
 * collected in the `stale` array so callers can archive them.
 */
async function filterStaleTasks(
  tasks: ApiTaskWithCompute[],
  owner: string,
  repo: string,
): Promise<{live: ApiTaskWithCompute[]; stale: ApiTaskWithCompute[]}> {
  const baseUrl = cloudEnvironmentUrl(owner, repo)

  const results = await Promise.all(
    tasks.map(async task => {
      try {
        const res = await reactFetchJSON(`${baseUrl}/${task.compute.resource_id}`, {})
        return {task, alive: res.status !== 404}
      } catch {
        // Network errors are not 404 — keep the task so we don't
        // accidentally archive during transient failures.
        return {task, alive: true}
      }
    }),
  )

  const live = results.filter(r => r.alive).map(r => r.task)
  const stale = results.filter(r => !r.alive).map(r => r.task)
  return {live, stale}
}

export function useCliTasks({owner, repo, currentUserId}: UseCliTasksOptions): UseCliTasksResult {
  const [tasks, setTasks] = useState<ApiTaskWithCompute[]>([])
  const [isLoading, setIsLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [fetchCounter, setFetchCounter] = useState(0)
  const pollAbortRef = useRef<(() => void) | null>(null)

  const refetch = useCallback(() => setFetchCounter(c => c + 1), [])

  // Poll until a task with matching compute.resource_id appears in the list.
  // The connector process creates the task asynchronously after the handshake,
  // so we need to retry a few times before the task shows up.
  const refetchUntilCodespace = useCallback(
    (codespaceId: string) => {
      pollAbortRef.current?.()
      let cancelled = false
      let attempt = 0

      pollAbortRef.current = () => {
        cancelled = true
      }

      const poll = async () => {
        while (!cancelled && attempt < CODESPACE_POLL_MAX_ATTEMPTS) {
          attempt++
          await new Promise<void>(resolve => setTimeout(resolve, CODESPACE_POLL_INTERVAL_MS))
          if (cancelled) return

          try {
            const result = await fetchAllCliTasks(owner, repo, currentUserId)
            if (cancelled) return

            const {live, stale} = await filterStaleTasks(result, owner, repo)
            if (cancelled) return

            for (const task of stale) {
              void (async () => {
                try {
                  await fetchCAPI({path: `/agents/repos/${owner}/${repo}/tasks/${task.id}/archive`, method: 'POST'})
                } catch {
                  // Best-effort archival — ignore failures
                }
              })()
            }

            const found = live.some(t => t.compute.resource_id === codespaceId)
            setTasks(live)
            if (found) return
          } catch {
            // Ignore fetch errors during polling; we'll try again.
          }
        }
      }

      void poll()
    },
    [owner, repo, currentUserId],
  )

  useEffect(() => {
    let cancelled = false

    async function fetchTasks() {
      setIsLoading(true)
      setError(null)

      try {
        const result = await fetchAllCliTasks(owner, repo, currentUserId)
        if (cancelled) return

        const {live, stale} = await filterStaleTasks(result, owner, repo)
        if (cancelled) return

        setTasks(live)

        // Archive stale tasks in the background — fire-and-forget
        for (const task of stale) {
          void (async () => {
            try {
              await fetchCAPI({path: `/agents/repos/${owner}/${repo}/tasks/${task.id}/archive`, method: 'POST'})
            } catch {
              // Best-effort archival — ignore failures
            }
          })()
        }
      } catch {
        if (!cancelled) {
          setError('Failed to load tasks')
        }
      } finally {
        if (!cancelled) {
          setIsLoading(false)
        }
      }
    }

    fetchTasks()
    return () => {
      cancelled = true
    }
  }, [owner, repo, currentUserId, fetchCounter])

  // Clean up any pending poll on unmount
  useEffect(() => {
    return () => {
      pollAbortRef.current?.()
    }
  }, [])

  const archiveTask = useCallback(
    async (taskId: string) => {
      await fetchCAPI({path: `/agents/repos/${owner}/${repo}/tasks/${taskId}/archive`, method: 'POST'})
      refetch()
    },
    [owner, repo, refetch],
  )

  return {tasks, isLoading, error, refetch, refetchUntilCodespace, archiveTask}
}
