import type {ApiTaskWithCompute} from '../hooks/use-cli-tasks'

export type CreationStatus =
  | {phase: 'idle'}
  | {phase: 'creating'}
  | {phase: 'provisioning'; codespaceId: string}
  | {phase: 'error'; message: string}

export type PanelState = {
  selectedTaskId: string | null
  creation: CreationStatus
  showSessionList: boolean
  hasAutoCreated: boolean
}

export type PanelAction =
  | {type: 'SELECT_TASK'; taskId: string}
  | {type: 'CLEAR_SELECTION'}
  | {type: 'START_CREATION'}
  | {type: 'CREATION_PROVISIONING'; codespaceId: string}
  | {type: 'CREATION_FAILED'; message: string}
  | {type: 'TOGGLE_SESSION_LIST'}
  | {type: 'HIDE_SESSION_LIST'}
  | {type: 'SET_AUTO_CREATED'}

export const initialPanelState: PanelState = {
  selectedTaskId: null,
  creation: {phase: 'idle'},
  showSessionList: false,
  hasAutoCreated: false,
}

export function panelReducer(state: PanelState, action: PanelAction): PanelState {
  switch (action.type) {
    case 'SELECT_TASK':
      return {...state, selectedTaskId: action.taskId, showSessionList: false, creation: {phase: 'idle'}}
    case 'CLEAR_SELECTION':
      return {...state, selectedTaskId: null}
    case 'START_CREATION':
      return {...state, selectedTaskId: null, creation: {phase: 'creating'}}
    case 'CREATION_PROVISIONING':
      return {...state, creation: {phase: 'provisioning', codespaceId: action.codespaceId}}
    case 'CREATION_FAILED':
      return {...state, creation: {phase: 'error', message: action.message}}
    case 'TOGGLE_SESSION_LIST':
      return {...state, showSessionList: !state.showSessionList}
    case 'HIDE_SESSION_LIST':
      return {...state, showSessionList: false}
    case 'SET_AUTO_CREATED':
      return {...state, hasAutoCreated: true}
    default:
      return state
  }
}

export function isCreating(state: PanelState): boolean {
  return state.creation.phase === 'creating' || state.creation.phase === 'provisioning'
}

/**
 * Derive the effective selected task from state + tasks.
 * Priority: explicit selection > newly created task > first task.
 */
export function resolveSelectedTask(
  state: PanelState,
  tasks: ApiTaskWithCompute[],
  isLoading: boolean,
): ApiTaskWithCompute | undefined {
  if (isLoading) return undefined

  // Explicit user selection
  if (state.selectedTaskId) {
    const task = tasks.find(t => t.id === state.selectedTaskId)
    if (task) return task
  }

  // Auto-select newly created task by codespace ID
  if (state.creation.phase === 'provisioning') {
    const csId = state.creation.codespaceId
    const task = tasks.find(t => t.compute?.resource_id === csId)
    if (task) return task
    // Still provisioning but task not yet in list — show spinner, not old session
    return undefined
  }

  // Creating phase — don't fall back to an existing task
  if (state.creation.phase === 'creating') return undefined

  return tasks[0]
}
