import {Spinner} from '@primer/react'
import {useEffect, useMemo, useRef, useState, useSyncExternalStore} from 'react'

import type {BannerFrame} from '../utils/banner-frames'
import {bannerFrames} from '../utils/banner-frames'
import bannerStyles from './CliBanner.module.css'

const colorValues: Record<string, string> = {
  b: '#656c76', // border
  t: '#e6edf3', // text
  B: '#79c0ff', // block_text
  s: '#656c76', // block_shadow
  h: '#d2a8ff', // head
  g: '#7ee8fa', // goggles
  e: '#3fb950', // eyes
  S: '#e3b341', // stars
  n: '#f0f6fc', // shine
}

function parseColors(encoded: string): Map<string, string> {
  const map = new Map<string, string>()
  if (!encoded) return map

  for (const group of encoded.split('|')) {
    const colonIdx = group.indexOf(':')
    if (colonIdx === -1) continue
    const code = group.slice(0, colonIdx)
    const color = colorValues[code]
    if (!color) continue

    const coords = group.slice(colonIdx + 1).split(',')
    for (let i = 0; i < coords.length - 1; i += 2) {
      map.set(`${coords[i]},${coords[i + 1]}`, color)
    }
  }
  return map
}

function colorizeRow(row: string, rowIndex: number, colorMap: Map<string, string>): React.ReactNode {
  const spans: React.ReactNode[] = []
  let currentColor: string | undefined
  let buffer = ''

  const flush = (key: string) => {
    if (buffer) {
      spans.push(
        <span key={key} style={currentColor ? {color: currentColor} : undefined}>
          {buffer}
        </span>,
      )
      buffer = ''
    }
  }

  for (let col = 0; col < row.length; col++) {
    const color = colorMap.get(`${rowIndex},${col}`)
    if (color !== currentColor) {
      flush(`${rowIndex}-${col}`)
      currentColor = color
    }
    buffer += row[col]
  }
  flush(`${rowIndex}-end`)

  return <div key={rowIndex}>{spans}</div>
}

function renderFrame(frame: BannerFrame, colorMap: Map<string, string>): React.ReactNode {
  const rows = frame.content.split('\n')
  return rows.map((row, i) => colorizeRow(row, i, colorMap))
}

interface CliBannerProps {
  showSpinner?: boolean
  statusText?: string
}

function subscribeToMotionPref(cb: () => void) {
  const mql = window.matchMedia('(prefers-reduced-motion: reduce)')
  mql.addEventListener('change', cb)
  return () => mql.removeEventListener('change', cb)
}

function getMotionPref() {
  return window.matchMedia('(prefers-reduced-motion: reduce)').matches
}

function getServerMotionPref() {
  return false
}

// Terminal-specific typography — intentionally not using Primer tokens
// because this renders on a forced-dark terminal background (#0c0c0c).
const terminalTypography: React.CSSProperties = {
  fontFamily: '"Menlo", "DejaVu Sans Mono", "Consolas", "Courier New", monospace',
  fontStyle: 'normal',
  fontSize: '13px',
  lineHeight: '1.3',
  color: '#e6edf3',
}

export function CliBanner({showSpinner = true, statusText = 'Launching Copilot CLI Session...'}: CliBannerProps) {
  const [frameIndex, setFrameIndex] = useState(0)
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  const prefersReducedMotion = useSyncExternalStore(subscribeToMotionPref, getMotionPref, getServerMotionPref)

  const lastFrame = bannerFrames[bannerFrames.length - 1]
  const frame = prefersReducedMotion ? lastFrame : (bannerFrames[frameIndex] ?? lastFrame)
  const colorMap = useMemo(() => (frame ? parseColors(frame.colors) : new Map<string, string>()), [frame])
  const isLastFrame = frameIndex >= bannerFrames.length - 1

  const RESTART_DELAY = 6000

  useEffect(() => {
    if (prefersReducedMotion) return
    if (!frame) return

    const delay = isLastFrame ? RESTART_DELAY : frame.duration
    timerRef.current = setTimeout(() => {
      setFrameIndex(isLastFrame ? 0 : i => i + 1)
    }, delay)

    return () => {
      if (timerRef.current) clearTimeout(timerRef.current)
    }
  }, [frameIndex, frame, isLastFrame, prefersReducedMotion])

  if (!frame) return null

  return (
    <div className={bannerStyles.Banner} style={terminalTypography}>
      <div aria-hidden="true">{renderFrame(frame, colorMap)}</div>
      {showSpinner && (
        <div className={`d-flex flex-items-center gap-2 ${bannerStyles.StatusRow}`} role="status">
          <Spinner size="small" />
          <span>{statusText}</span>
        </div>
      )}
    </div>
  )
}
