import {ArchiveIcon, TerminalIcon} from '@primer/octicons-react'
import {IconButton, Spinner, Tooltip} from '@primer/react'
import {useState} from 'react'

import type {ApiTaskWithCompute} from '../hooks/use-cli-tasks'
import styles from './WebTerminalPanel.module.css'

export interface CliTaskListProps {
  tasks: ApiTaskWithCompute[]
  isLoading: boolean
  error: string | null
  activeTaskId?: string
  isCreating?: boolean
  onTaskClick: (task: ApiTaskWithCompute) => void
  onArchive: (task: ApiTaskWithCompute) => Promise<void>
}

export function CliTaskList({
  tasks,
  isLoading,
  error,
  activeTaskId,
  isCreating,
  onTaskClick,
  onArchive,
}: CliTaskListProps) {
  const [archivingId, setArchivingId] = useState<string | null>(null)

  if (isLoading) {
    return (
      <div className={styles.TaskListEmpty} role="status">
        <Spinner size="small" />
      </div>
    )
  }

  if (error) {
    return (
      <div className={styles.TaskListEmpty} role="alert">
        <p className={styles.TaskListEmptyText}>{error}</p>
      </div>
    )
  }

  if (tasks.length === 0 && !isCreating) {
    return (
      <div className={styles.TaskListEmpty}>
        <p className={styles.TaskListEmptyText}>No sessions</p>
      </div>
    )
  }

  const handleArchive = async (task: ApiTaskWithCompute) => {
    setArchivingId(task.id)
    try {
      await onArchive(task)
    } finally {
      setArchivingId(null)
    }
  }

  return (
    <ul className={styles.TaskList}>
      {isCreating && (
        <li>
          <div className={styles.TaskListItem} style={{opacity: 0.7}}>
            <span className={styles.TaskListItemSelect}>
              <Spinner size="small" />
              <span className={styles.TaskListItemTitle}>Creating...</span>
            </span>
          </div>
        </li>
      )}
      {tasks.map(task => {
        const label = task.name || 'CLI session'
        const isActive = task.id === activeTaskId
        return (
          <li key={task.id}>
            <div className={`${styles.TaskListItem} ${isActive ? styles.TaskListItemActive : ''}`}>
              <Tooltip text={label} direction="w">
                <button
                  className={styles.TaskListItemSelect}
                  onClick={() => onTaskClick(task)}
                  type="button"
                  aria-current={isActive ? 'true' : undefined}
                >
                  <TerminalIcon size={16} />
                  <span className={styles.TaskListItemTitle}>{label}</span>
                </button>
              </Tooltip>
              {archivingId === task.id ? (
                <Spinner size="small" />
              ) : (
                <IconButton
                  icon={ArchiveIcon}
                  aria-label={`Archive ${label}`}
                  variant="invisible"
                  size="small"
                  className={styles.TaskListItemAction}
                  onClick={() => handleArchive(task)}
                />
              )}
            </div>
          </li>
        )
      })}
    </ul>
  )
}
